pub fn solve(w: i8, a: i8, b: i8) -> i8 {
    // Promote to a wider type to avoid overflow on subtraction/abs.
    let w16 = w as i16;
    let d = (a as i16 - b as i16).abs();
    let ans = (d - w16).max(0);

    // Assuming the expected answer fits in i8 as per the task's signature.
    ans as i8
}

